/**
 * Generates the authorization catalog (permission keys, role names, global
 * role aliases) for backend, admin and app from a single source:
 *  - permissions: prisma/permissions seed + migrations (see ./catalog-source)
 *  - roles:       prisma/authz/roles.json
 *  - aliases:     src/common/guards/global-role-aliases.ts
 *
 * Usage:
 *   pnpm authz:generate   write generated files
 *   pnpm authz:check      regenerate in memory, exit 1 listing stale files
 *
 * Sibling repos are written only when their root exists:
 *   SACDIA_ADMIN_ROOT (default ../sacdia-admin)
 *   SACDIA_APP_ROOT   (default ../sacdia-app)
 */
import * as fs from 'fs';
import * as path from 'path';
import {
  loadPermissionCatalog,
  type CatalogPermission,
} from './catalog-source';
import { GLOBAL_ROLE_ALIASES } from '../../src/common/guards/global-role-aliases';

export const GENERATED_HEADER =
  '// GENERATED by scripts/authz/generate-catalog.ts — do not edit. Run `pnpm authz:generate` in sacdia-backend.';

export type RoleSource = {
  role_name: string;
  description?: string;
  role_category: 'GLOBAL' | 'CLUB';
  active?: boolean;
};

export type AliasSource = Record<string, readonly string[]>;

export type GeneratedFile = {
  repo: 'backend' | 'admin' | 'app';
  /** Path relative to that repo's root (posix separators). */
  relPath: string;
  content: string;
};

export type CatalogInput = {
  permissions: CatalogPermission[];
  roles: RoleSource[];
  aliases: AliasSource;
  /** Repos to emit for. Backend is always emitted. */
  repos?: { admin?: boolean; app?: boolean };
};

const BACKEND_DIR = 'src/common/authorization/generated';
const ADMIN_DIR = 'src/lib/auth/generated';
const APP_DIR = 'lib/core/authorization/generated';
const DART_MAX = 80;
const TS_MAX = 80;

const byString = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
const sorted = (xs: readonly string[]) => [...xs].sort(byString);

export function tsConstName(key: string): string {
  return key.toUpperCase().replace(/[:-]/g, '_');
}

export function dartMemberName(key: string): string {
  const parts = key.split(/[:_-]/).filter(Boolean);
  return parts
    .map((p, i) => (i === 0 ? p : p.charAt(0).toUpperCase() + p.slice(1)))
    .join('');
}

function assertNoCollisions(keys: string[]): void {
  const check = (label: string, fn: (k: string) => string) => {
    const seen = new Map<string, string>();
    const clashes: string[] = [];
    for (const k of keys) {
      const n = fn(k);
      const prev = seen.get(n);
      if (prev !== undefined)
        clashes.push(`${label} "${n}": "${prev}" vs "${k}"`);
      else seen.set(n, k);
    }
    if (clashes.length) {
      throw new Error(
        `Permission name collision(s):\n  ${clashes.join('\n  ')}`,
      );
    }
  };
  check('TS', tsConstName);
  check('Dart', dartMemberName);
}

function tsKey(k: string): string {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(k) ? k : `'${k}'`;
}

function tsStringArray(
  indent: string,
  prefix: string,
  items: readonly string[],
  suffix: string,
): string {
  const inline = `${indent}${prefix}[${items.map((i) => `'${i}'`).join(', ')}]${suffix}`;
  if (inline.length <= TS_MAX) return inline;
  return [
    `${indent}${prefix}[`,
    ...items.map((i) => `${indent}  '${i}',`),
    `${indent}]${suffix}`,
  ].join('\n');
}

function tsPermissionEntry(k: string): string {
  const line = `  ${tsConstName(k)}: '${k}',`;
  return line.length <= TS_MAX ? line : `  ${tsConstName(k)}:\n    '${k}',`;
}

function tsPermissionKeys(active: string[], deprecated: string[]): string {
  const arr = (name: string, items: string[]) =>
    items.length === 0
      ? `export const ${name} = [] as const;`
      : `export const ${name} = [\n${items.map((k) => `  '${k}',`).join('\n')}\n] as const;`;
  return `${GENERATED_HEADER}

${arr('PERMISSION_KEYS', active)}

export type PermissionKey = (typeof PERMISSION_KEYS)[number];

${arr('DEPRECATED_PERMISSION_KEYS', deprecated)}

export const Permission = {
${active.map(tsPermissionEntry).join('\n')}
} as const;
`;
}

function tsRoleNames(globals: string[], clubs: string[]): string {
  const arr = (name: string, items: string[]) =>
    `export const ${name} = [\n${items.map((k) => `  '${k}',`).join('\n')}\n] as const;`;
  return `${GENERATED_HEADER}

${arr('GLOBAL_ROLE_NAMES', globals)}

${arr('CLUB_ROLE_NAMES', clubs)}

export type GlobalRoleName = (typeof GLOBAL_ROLE_NAMES)[number];

export type ClubRoleName = (typeof CLUB_ROLE_NAMES)[number];

export type RoleName = GlobalRoleName | ClubRoleName;
`;
}

function tsRoleAliases(aliases: AliasSource): string {
  const body = sorted(Object.keys(aliases))
    .map((k) => tsStringArray('  ', `${tsKey(k)}: `, aliases[k], ','))
    .join('\n');
  return `${GENERATED_HEADER}

import type { GlobalRoleName } from './role-names';

export const GLOBAL_ROLE_ALIASES: Record<
  GlobalRoleName,
  readonly GlobalRoleName[]
> = {
${body}
};
`;
}

function dartList(
  indent: string,
  prefix: string,
  items: readonly string[],
  suffix: string,
): string {
  const inline = `${indent}${prefix}[${items.map((i) => `'${i}'`).join(', ')}]${suffix}`;
  if (inline.length <= DART_MAX) return inline;
  return [
    `${indent}${prefix}[`,
    ...items.map((i) => `${indent}  '${i}',`),
    `${indent}]${suffix}`,
  ].join('\n');
}

function dartPermissionKeys(active: string[]): string {
  const members = active.map((k) => {
    const line = `  static const String ${dartMemberName(k)} = '${k}';`;
    return line.length <= DART_MAX
      ? line
      : `  static const String ${dartMemberName(k)} =\n      '${k}';`;
  });
  return `${GENERATED_HEADER}

const Set<String> kPermissionKeys = {
${active.map((k) => `  '${k}',`).join('\n')}
};

abstract final class Permissions {
${members.join('\n')}
}
`;
}

function dartRoleNames(globals: string[], clubs: string[]): string {
  const arr = (name: string, items: string[]) =>
    `const List<String> ${name} = [\n${items.map((k) => `  '${k}',`).join('\n')}\n];`;
  return `${GENERATED_HEADER}

${arr('kGlobalRoleNames', globals)}

${arr('kClubRoleNames', clubs)}
`;
}

function dartRoleAliases(aliases: AliasSource): string {
  const body = sorted(Object.keys(aliases))
    .map((k) => dartList('  ', `'${k}': `, aliases[k], ','))
    .join('\n');
  return `${GENERATED_HEADER}

const Map<String, List<String>> kGlobalRoleAliases = {
${body}
};
`;
}

/** Pure: builds every output file from the given inputs. */
export function buildOutputs(input: CatalogInput): GeneratedFile[] {
  const active = sorted(
    input.permissions.filter((p) => p.active).map((p) => p.key),
  );
  const deprecated = sorted(
    input.permissions.filter((p) => !p.active).map((p) => p.key),
  );
  assertNoCollisions([...active]);

  const globals = sorted(
    input.roles
      .filter((r) => r.role_category === 'GLOBAL')
      .map((r) => r.role_name),
  );
  const clubs = sorted(
    input.roles
      .filter((r) => r.role_category === 'CLUB')
      .map((r) => r.role_name),
  );

  const globalSet = new Set(globals);
  const unknown: string[] = [];
  for (const [k, vs] of Object.entries(input.aliases)) {
    for (const v of [k, ...vs])
      if (!globalSet.has(v)) unknown.push(`${k} -> ${v}`);
  }
  if (unknown.length) {
    throw new Error(
      `Role aliases reference non-global roles:\n  ${unknown.join('\n  ')}`,
    );
  }
  const missingKeys = globals.filter((g) => !(g in input.aliases));
  if (missingKeys.length) {
    throw new Error(`Role aliases missing for: ${missingKeys.join(', ')}`);
  }

  const ts = {
    'permission-keys.ts': tsPermissionKeys(active, deprecated),
    'role-names.ts': tsRoleNames(globals, clubs),
    'role-aliases.ts': tsRoleAliases(input.aliases),
  };
  const files: GeneratedFile[] = [];
  for (const [name, content] of Object.entries(ts)) {
    files.push({ repo: 'backend', relPath: `${BACKEND_DIR}/${name}`, content });
    if (input.repos?.admin) {
      files.push({ repo: 'admin', relPath: `${ADMIN_DIR}/${name}`, content });
    }
  }
  if (input.repos?.app) {
    const dart = {
      'permission_keys.dart': dartPermissionKeys(active),
      'role_names.dart': dartRoleNames(globals, clubs),
      'role_aliases.dart': dartRoleAliases(input.aliases),
    };
    for (const [name, content] of Object.entries(dart)) {
      files.push({ repo: 'app', relPath: `${APP_DIR}/${name}`, content });
    }
  }
  return files;
}

export type Roots = { backend: string; admin?: string; app?: string };

/** Sibling roots from env / defaults, only those that exist on disk. */
export function resolveRoots(
  backendRoot: string,
  env: NodeJS.ProcessEnv = process.env,
): Roots {
  const pick = (value: string | undefined, fallback: string) => {
    const p = path.resolve(backendRoot, value || fallback);
    return fs.existsSync(p) && fs.statSync(p).isDirectory() ? p : undefined;
  };
  return {
    backend: backendRoot,
    admin: pick(env.SACDIA_ADMIN_ROOT, '../sacdia-admin'),
    app: pick(env.SACDIA_APP_ROOT, '../sacdia-app'),
  };
}

export function loadRoles(backendRoot: string): RoleSource[] {
  return JSON.parse(
    fs.readFileSync(path.join(backendRoot, 'prisma/authz/roles.json'), 'utf8'),
  ) as RoleSource[];
}

export function generate(roots: Roots): Array<GeneratedFile & { abs: string }> {
  const files = buildOutputs({
    permissions: loadPermissionCatalog(roots.backend),
    roles: loadRoles(roots.backend),
    aliases: GLOBAL_ROLE_ALIASES,
    repos: { admin: !!roots.admin, app: !!roots.app },
  });
  return files.map((f) => ({
    ...f,
    abs: path.join(roots[f.repo] as string, f.relPath),
  }));
}

/** Absolute paths whose on-disk content differs from the generated one. */
export function diffOutputs(
  files: Array<GeneratedFile & { abs: string }>,
): string[] {
  return files
    .filter(
      (f) =>
        !fs.existsSync(f.abs) || fs.readFileSync(f.abs, 'utf8') !== f.content,
    )
    .map((f) => f.abs);
}

export function writeOutputs(
  files: Array<GeneratedFile & { abs: string }>,
): string[] {
  const changed: string[] = [];
  for (const f of files) {
    if (fs.existsSync(f.abs) && fs.readFileSync(f.abs, 'utf8') === f.content) {
      continue;
    }
    fs.mkdirSync(path.dirname(f.abs), { recursive: true });
    fs.writeFileSync(f.abs, f.content);
    changed.push(f.abs);
  }
  return changed;
}

/**
 * Backend-only comparison used by `--check` in CI: sibling repos are skipped
 * unless their root exists, so a lone backend checkout never fails on them.
 */
export function main(argv: string[], backendRoot: string): number {
  const check = argv.includes('--check');
  const files = generate(resolveRoots(backendRoot));
  if (check) {
    const stale = diffOutputs(files);
    if (stale.length) {
      console.error(
        `authz catalog is out of date. Run \`pnpm authz:generate\`. Differing files:\n${stale.map((s) => `  ${s}`).join('\n')}`,
      );
      return 1;
    }
    console.log(`authz catalog up to date (${files.length} files).`);
    return 0;
  }
  const changed = writeOutputs(files);
  console.log(
    `authz catalog: ${files.length} files, ${changed.length} written.`,
  );
  for (const c of changed) console.log(`  ${c}`);
  return 0;
}

if (require.main === module) {
  process.exit(main(process.argv.slice(2), path.resolve(__dirname, '../..')));
}
